const QUESTIONS = [
  {
    id: 'q1',
    text: 'Which of the following are statically typed languages?',
    helpText: 'Statically typed languages check types at compile time rather than at runtime, catching type errors early in development.',
    options: [
      { id: 'q1a', label: 'TypeScript' },
      { id: 'q1b', label: 'Python' },
      { id: 'q1c', label: 'Rust' },
      { id: 'q1d', label: 'Java' },
    ],
    correct: new Set(['q1a', 'q1c', 'q1d']),
  },
  {
    id: 'q2',
    text: 'Which languages are primarily used for systems or low-level programming?',
    options: [
      { id: 'q2a', label: 'C' },
      { id: 'q2b', label: 'Ruby' },
      { id: 'q2c', label: 'C++' },
      { id: 'q2d', label: 'Rust' },
    ],
    correct: new Set(['q2a', 'q2c', 'q2d']),
  },
  {
    id: 'q3',
    text: 'Which of the following languages support first-class functions?',
    options: [
      { id: 'q3a', label: 'JavaScript' },
      { id: 'q3b', label: 'Haskell' },
      { id: 'q3c', label: 'Python' },
      { id: 'q3d', label: 'C (prior to C99)' },
    ],
    correct: new Set(['q3a', 'q3b', 'q3c']),
  },
];

const CHECK_ICON = `
  <svg aria-hidden="true" viewBox="0 0 12 12" fill="none" xmlns="http://www.w3.org/2000/svg">
    <path d="M2 6.5L4.5 9L10 3.5" stroke="white" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>
  </svg>`;

function QuizApp() {
  const root = document.getElementById('quiz-root');

  // ── Build DOM ──────────────────────────────────────────────────────────────

  const container = el('div', { className: 'quiz-container' });

  const header = el('header', { className: 'quiz-header' }, [
    el('h1', {}, 'Computer Languages Quiz'),
    el('p', {}, 'Select all answers that apply to each question, then submit.'),
  ]);
  container.appendChild(header);

  const form = el('form', { id: 'quiz-form', noValidate: true });

  QUESTIONS.forEach((q, idx) => {
    form.appendChild(buildQuestion(q, idx + 1));
  });

  // Submit row
  const submitRow = el('div', { className: 'submit-row' });

  const resetBtn = el('button', {
    type: 'button',
    className: 'btn-reset',
    textContent: 'Reset',
    'aria-label': 'Reset all answers',
  });
  resetBtn.addEventListener('click', resetQuiz);

  const submitBtn = el('button', {
    type: 'submit',
    className: 'btn-submit',
    textContent: 'Submit Quiz',
  });

  submitRow.appendChild(resetBtn);
  submitRow.appendChild(submitBtn);
  form.appendChild(submitRow);

  // Result banner
  const resultBanner = el('div', {
    className: 'result-banner',
    id: 'result-banner',
    role: 'alert',
    'aria-live': 'polite',
  });
  const resultTitle = el('h2', { id: 'result-title' });
  const scoreDisplay = el('div', { className: 'score-display', id: 'score-display' });
  const resultMsg = el('p', { id: 'result-msg' });
  resultBanner.appendChild(resultTitle);
  resultBanner.appendChild(scoreDisplay);
  resultBanner.appendChild(resultMsg);

  container.appendChild(form);
  container.appendChild(resultBanner);
  root.appendChild(container);

  // ── Event: Submit ──────────────────────────────────────────────────────────

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    let totalCorrect = 0;

    QUESTIONS.forEach((q) => {
      const selected = getSelected(q.id);
      const isCorrect =
        selected.size === q.correct.size &&
        [...selected].every((id) => q.correct.has(id));

      if (isCorrect) totalCorrect++;
      applyResultStyles(q, selected);
    });

    // Disable all checkboxes
    form.querySelectorAll('input[type="checkbox"]').forEach((cb) => {
      cb.disabled = true;
    });
    submitBtn.disabled = true;
    submitBtn.textContent = 'Submitted';

    showResult(totalCorrect);
  });

  // ── Helpers ────────────────────────────────────────────────────────────────

  function buildQuestion(q, num) {
    const fieldset = el('div', { className: 'form-field' });

    const meta = el('div', { className: 'question-meta' });
    meta.appendChild(el('span', { className: 'question-number' }, `Question ${num}`));
    fieldset.appendChild(meta);

    const labelEl = el('p', { className: 'question-label', id: `${q.id}-label` }, q.text);
    fieldset.appendChild(labelEl);

    if (q.helpText) {
      fieldset.appendChild(el('p', { className: 'help-text' }, q.helpText));
    }

    const group = el('ul', {
      className: 'options-list',
      role: 'group',
      'aria-labelledby': `${q.id}-label`,
    });

    q.options.forEach((opt) => {
      const li = el('li', { className: 'option', id: `option-${opt.id}` });

      const checkbox = el('input', {
        type: 'checkbox',
        id: opt.id,
        name: q.id,
        value: opt.id,
      });

      const label = el('label', { htmlFor: opt.id });

      const box = el('span', { className: 'checkbox-box', 'aria-hidden': 'true' });
      box.innerHTML = CHECK_ICON;

      label.appendChild(box);
      label.appendChild(el('span', { className: 'option-text' }, opt.label));

      li.appendChild(checkbox);
      li.appendChild(label);
      group.appendChild(li);
    });

    fieldset.appendChild(group);
    return fieldset;
  }

  function getSelected(questionId) {
    const checked = form.querySelectorAll(`input[name="${questionId}"]:checked`);
    return new Set([...checked].map((cb) => cb.value));
  }

  function applyResultStyles(q, selected) {
    q.options.forEach((opt) => {
      const li = document.getElementById(`option-${opt.id}`);
      li.classList.remove('correct', 'wrong', 'missed');

      const isSelected = selected.has(opt.id);
      const isCorrect = q.correct.has(opt.id);

      if (isSelected && isCorrect) li.classList.add('correct');
      else if (isSelected && !isCorrect) li.classList.add('wrong');
      else if (!isSelected && isCorrect) li.classList.add('missed');

      // Ensure checkbox box icon is visible for result state
      const checkbox = document.getElementById(opt.id);
      const box = li.querySelector('.checkbox-box');
      if (!isSelected && isCorrect) {
        box.innerHTML = CHECK_ICON;
        box.style.borderColor = '#ffa726';
        box.style.background = 'transparent';
      }
    });
  }

  function showResult(score) {
    const total = QUESTIONS.length;
    const pct = Math.round((score / total) * 100);
    const messages = [
      'Keep studying — you'll get there! 💪',
      'Not bad, but there's room to grow. 📚',
      'Great job! You really know your languages. 🚀',
      'Perfect score! You're a language expert! 🏆',
    ];
    const msgIdx = score === 0 ? 0 : score === 1 ? 1 : score < total ? 2 : 3;

    document.getElementById('result-title').textContent = 'Quiz Complete!';
    document.getElementById('score-display').textContent = `${score} / ${total}`;
    document.getElementById('result-msg').textContent = messages[msgIdx];

    const banner = document.getElementById('result-banner');
    banner.classList.add('visible');
    banner.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  }

  function resetQuiz() {
    // Uncheck all, remove result classes, re-enable inputs
    form.querySelectorAll('input[type="checkbox"]').forEach((cb) => {
      cb.checked = false;
      cb.disabled = false;
    });

    QUESTIONS.forEach((q) => {
      q.options.forEach((opt) => {
        const li = document.getElementById(`option-${opt.id}`);
        li.classList.remove('correct', 'wrong', 'missed');
        const box = li.querySelector('.checkbox-box');
        box.style.borderColor = '';
        box.style.background = '';
      });
    });

    const submitBtn = form.querySelector('.btn-submit');
    submitBtn.disabled = false;
    submitBtn.textContent = 'Submit Quiz';

    document.getElementById('result-banner').classList.remove('visible');
    container.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }
}

// ── Utility: createElement with props ─────────────────────────────────────────

function el(tag, props = {}, children) {
  const node = document.createElement(tag);
  Object.entries(props).forEach(([key, val]) => {
    if (key === 'className') node.className = val;
    else if (key === 'textContent') node.textContent = val;
    else if (key === 'htmlFor') node.htmlFor = val;
    else node.setAttribute(key, val);
  });
  if (typeof children === 'string') {
    node.textContent = children;
  } else if (Array.isArray(children)) {
    children.forEach((c) => node.appendChild(c));
  }
  return node;
}

document.addEventListener('DOMContentLoaded', QuizApp);
